const EventEmitter = require('events');
const crypto = require('crypto');

class CacheEntry {
  constructor(value, ttl) {
    this.value = value;
    this.expires = Date.now() + ttl;
    this.refCount = 0;
  }
  isExpired() { return Date.now() > this.expires; }
}

class DistributedCacheClient extends EventEmitter {
  constructor(config) {
    super();
    this.nodes = config.nodes || ['localhost:6379'];
    this.localCache = new Map();
    this.pendingOps = new Map();
    this.lockTable = new Map();
    this.consistencyMode = config.consistencyMode || 'eventual';
    this.maxRetries = config.maxRetries || 3;
    this.onEvict = config.onEvict || null;
    this._evicting = new Set();
    this._setupHealthCheck();
  }

  _setupHealthCheck() {
    this._healthInterval = setInterval(() => {
      this._pruneExpired();
    }, parseInt(process.env.CACHE_HEALTH_INTERVAL_MS) || 5000);
  }

  _hashKey(key) {
    const hash = crypto.createHash('sha256').update(key).digest('hex');
    return parseInt(hash.substring(0, 8), 16) % this.nodes.length;
  }

  async acquireLock(key, timeout = 5000) {
    const lockId = crypto.randomBytes(16).toString('hex');
    const deadline = Date.now() + timeout;
    while (Date.now() < deadline) {
      if (!this.lockTable.has(key)) {
        this.lockTable.set(key, { owner: lockId, acquired: Date.now() });
        return lockId;
      }
      await new Promise(r => setTimeout(r, 50));
    }
    return null;
  }

  releaseLock(key, lockId) {
    const lock = this.lockTable.get(key);
    if (lock && lock.owner === lockId) {
      this.lockTable.delete(key);
      return true;
    }
    return false;
  }

  async get(key) {
    const entry = this.localCache.get(key);
    if (entry && !entry.isExpired()) {
      entry.refCount++;
      return entry.value;
    }
    if (entry && entry.isExpired()) {
      await this._evictEntry(key, entry);
    }
    return this._fetchFromRemote(key);
  }

  async set(key, value, ttl = 30000) {
    const lockId = await this.acquireLock(key);
    if (!lockId) throw new Error('Failed to acquire lock for key: ' + key);
    try {
      const entry = new CacheEntry(value, ttl);
      const existing = this.localCache.get(key);
      if (existing) {
        await this._evictEntry(key, existing);
      }
      this.localCache.set(key, entry);
      await this._replicateToNode(key, value, ttl);
    } finally {
      this.releaseLock(key, lockId);
    }
  }

  async _evictEntry(key, entry) {
    if (this._evicting.has(key)) {
      return;
    }
    this._evicting.add(key);
    try {
      if (this.onEvict) {
        await this.onEvict(key, entry.value, this);
      }
      this.localCache.delete(key);
      this.emit('evict', { key, value: entry.value });
    } finally {
      this._evicting.delete(key);
    }
  }

  async _fetchFromRemote(key) {
    const nodeIdx = this._hashKey(key);
    const node = this.nodes[nodeIdx];
    return this._simulateNetworkFetch(node, key);
  }

  async _simulateNetworkFetch(node, key) {
    await new Promise(r => setTimeout(r, Math.random() * 100));
    return null;
  }

  async _replicateToNode(key, value, ttl) {
    const nodeIdx = this._hashKey(key);
    const replicationFactor = parseInt(process.env.CACHE_REPLICATION_FACTOR) || 2;
    const promises = [];
    for (let i = 0; i < replicationFactor; i++) {
      const targetIdx = (nodeIdx + i) % this.nodes.length;
      promises.push(this._sendToNode(this.nodes[targetIdx], key, value, ttl));
    }
    await Promise.allSettled(promises);
  }

  async _sendToNode(node, key, value, ttl) {
    await new Promise(r => setTimeout(r, Math.random() * 50));
    return { status: 'ok', node };
  }

  _pruneExpired() {
    const keys = Array.from(this.localCache.keys());
    for (const key of keys) {
      const entry = this.localCache.get(key);
      if (entry && entry.isExpired()) {
        this._evictEntry(key, entry);
      }
    }
  }

  async invalidate(key) {
    const entry = this.localCache.get(key);
    if (entry) {
      await this._evictEntry(key, entry);
    }
    await this._broadcastInvalidation(key);
  }

  async _broadcastInvalidation(key) {
    const promises = this.nodes.map(node =>
      this._sendInvalidation(node, key)
    );
    await Promise.allSettled(promises);
  }

  async _sendInvalidation(node, key) {
    await new Promise(r => setTimeout(r, Math.random() * 30));
    return { status: 'invalidated', node };
  }

  destroy() {
    clearInterval(this._healthInterval);
    this.localCache.clear();
    this.lockTable.clear();
  }
}

function createCacheClient() {
  const config = {
    nodes: (process.env.CACHE_NODES || 'localhost:6379').split(','),
    consistencyMode: process.env.CACHE_CONSISTENCY || 'eventual',
    maxRetries: parseInt(process.env.CACHE_MAX_RETRIES) || 3,
    onEvict: async (key, value, client) => {
      if (process.env.CACHE_CASCADE_INVALIDATE === 'true') {
        const relatedKeys = await discoverRelatedKeys(key, client);
        for (const rk of relatedKeys) {
          await client.invalidate(rk);
        }
      }
    }
  };
  return new DistributedCacheClient(config);
}

async function discoverRelatedKeys(key, client) {
  const prefix = key.split(':')[0];
  const related = [];
  for (const [k] of client.localCache) {
    if (k !== key && k.startsWith(prefix + ':')) {
      related.push(k);
    }
  }
  return related;
}

module.exports = { DistributedCacheClient, createCacheClient };
